    <div class="form-inline"><label for="ucm-services-site"><?php echo _('PBX site'); ?></label> <select id="ucm-services-site" class="form-control"><?php foreach($sites as $site): ?><option value="<?php echo (int)$site['id']; ?>" <?php echo (int)$site['id']===$localId?'selected':''; ?>><?php echo htmlspecialchars((string)$site['name']); ?><?php echo !empty($site['is_local'])?' — '._('Local'):''; ?></option><?php endforeach; ?></select> <button type="button" class="btn btn-default" id="ucm-services-refresh"><i class="fa fa-refresh"></i> <?php echo _('Refresh'); ?></button></div>
  </div>
