        <label class="checkbox-inline"><input type="checkbox" class="ucm-service-format" value="grandstream"> <?php echo _('Grandstream XMLApp'); ?></label>
      </div><p class="help-block"><?php echo _('The service is omitted from phone families you do not select. Device profiles without a supported application entry remain fail-closed.'); ?></p></div>
      <div class="form-group"><label for="ucm-service-models"><?php echo _('Exact models (optional)'); ?></label><select class="form-control" id="ucm-service-models" multiple size="7"></select><p class="help-block"><?php echo _('Leave empty for every supported model in the selected families. Selecting models makes the service fail closed on unknown or different phones.'); ?></p></div>
      <div id="ucm-service-text"><div class="form-group"><label><?php echo _('Notice text'); ?></label><textarea class="form-control" name="body" rows="6" maxlength="1200"></textarea></div></div>
      <div id="ucm-service-dials"><div class="ucm-card-heading"><div><h4><?php echo _('Quick-dial entries'); ?></h4><p><?php echo _('Cisco XML, Yealink XML Browser and Grandstream XMLApp can dial these. Cisco 7940/7960 displays the number for manual dialing because its SIP XML client lacks Execute support.'); ?></p></div><button type="button" class="btn btn-default btn-sm" id="ucm-service-add-dial"><?php echo _('Add destination'); ?></button></div><div id="ucm-service-dial-rows"></div></div>
      <div class="text-right"><button type="button" class="btn btn-default" id="ucm-service-cancel"><?php echo _('Cancel'); ?></button> <button type="submit" class="btn btn-primary"><?php echo _('Save on selected PBX'); ?></button></div>
    </form>
  </section>

  <section class="ucm-card">
    <div class="ucm-card-heading"><div><h3><?php echo _('How phones enter the catalog'); ?></h3><p><?php echo _('A rebuild is needed once to place the service URL. Later catalog edits are served immediately from that PBX. Unsupported combinations remain fail-closed instead of receiving guessed vendor settings.'); ?></p></div></div>
    <div class="table-responsive"><table class="table table-condensed" id="ucm-services-capabilities"><thead><tr><th><?php echo _('Fleet'); ?></th><th><?php echo _('Entry point'); ?></th><th><?php echo _('Catalog'); ?></th><th><?php echo _('One-touch dial'); ?></th><th><?php echo _('Provisioning note'); ?></th></tr></thead><tbody></tbody></table></div>
    <details><summary><strong><?php echo _('Endpoint URLs and template instructions'); ?></strong></summary><p><?php echo _('Cisco XML and legacy Cisco are wired automatically. For a Yealink desk key choose XML Browser and enter {services}. Grandstream GXP/GRP receive P337/P352 automatically and may also use an XML Application key. DECT handsets inherit their directory from the provisioned base.'); ?></p><dl class="dl-horizontal" id="ucm-services-urls"></dl></details>
  </section>

  <section class="ucm-card"><details><summary><strong><?php echo _('Security and compatibility'); ?></strong></summary><ul><li><?php echo _('The URL contains a random site-local read token. Rotate it only by deleting the phone_services_token setting and rebuilding the affected phones.'); ?></li><li><?php echo _('The endpoint is read-only. Quick Dial returns a vendor dial instruction; it cannot change PBX configuration or execute server commands.'); ?></li><li><?php echo _('Cisco 7940/7960 use a short PATH_INFO URL and only their documented Menu/Text/Input/Directory subset.'); ?></li><li><?php echo _('The managed phone-services base URL is configured under Settings. It preserves an optional port and base path; embedded credentials, query strings and fragments are rejected. Legacy Cisco logos and services still require a phone-reachable plain-HTTP endpoint.'); ?></li></ul></details></section>

  <div class="modal fade" id="ucm-services-preview" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><div class="modal-header"><button type="button" class="close" data-dismiss="modal">&times;</button><h4><?php echo _('Vendor XML preview'); ?></h4></div><div class="modal-body"><div class="form-inline"><label for="ucm-services-preview-format"><?php echo _('Renderer'); ?></label> <select id="ucm-services-preview-format" class="form-control"><option value="cisco">Cisco XML</option><option value="cisco_legacy">Cisco 7940/7960</option><option value="yealink">Yealink XML Browser</option><option value="grandstream">Grandstream XMLApp</option></select> <label for="ucm-services-preview-model"><?php echo _('Model'); ?></label> <select id="ucm-services-preview-model" class="form-control"></select></div><div id="ucm-services-preview-warning" class="alert alert-warning" style="display:none;margin-top:12px"></div><pre id="ucm-services-preview-code" style="margin-top:12px;max-height:520px;overflow:auto"></pre></div></div></div></div>
</div>

<script>
(function($){'use strict';
var localId=<?php echo (int)$localId; ?>, allFormats=['cisco','cisco_legacy','yealink','grandstream'];
var state={services:[],models:[],previewCache:{},busy:false,previewKey:'root',readOnly:false,siteCache:{}};
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function site(){return $('#ucm-services-site').val();} function siteName(){return $('#ucm-services-site option:selected').text();}
function feedback(m,ok,working,warning){$('#ucm-services-feedback').removeClass('alert-info alert-success alert-warning alert-danger').addClass(working?'alert-info':(warning?'alert-warning':(ok?'alert-success':'alert-danger'))).html((working?'<i class="fa fa-spinner fa-spin"></i> ':'')+esc(m));}
function applyReadOnly(){$('#ucm-service-add,.ucm-service-edit,.ucm-service-delete,.ucm-service-move').prop('disabled',state.readOnly);if(!state.readOnly){$('#ucm-services-table tbody tr:first .ucm-service-move[data-dir="-1"],#ucm-services-table tbody tr:last .ucm-service-move[data-dir="1"]').prop('disabled',true);}}
function call(data,msg){if(state.busy)return $.Deferred().reject('Another request is running').promise();state.busy=true;feedback(msg,true,true);$('#ucm-services-app button,#ucm-services-app select').prop('disabled',true);return window.ucmpAjax({data:$.extend({command:'phoneservices',site_id:site()},data)}).then(function(resp){var r=(resp&&resp.result)||{};if(!(resp&&resp.status)||r.ok===false)return $.Deferred().reject(r.message||(resp&&resp.message)||'Request failed');return r;},function(xhr){return $.Deferred().reject((xhr.responseJSON&&xhr.responseJSON.message)||'Request failed');}).always(function(){state.busy=false;$('#ucm-services-app button,#ucm-services-app select').prop('disabled',false);applyReadOnly();});}
function remember(r){var safe=$.extend(true,{},r);delete safe.urls;state.siteCache[site()]=safe;}
function load(){closeEditor();var id=site();call({op:'list'},'Loading services from '+siteName()+'…').done(function(r){remember(r);state.readOnly=Number(id)!==localId&&!r.urls;render(r);feedback(state.readOnly?'Site is unreachable; showing its last-known catalog snapshot and cached output previews. Editing is disabled.':'Service catalog refreshed from '+siteName()+'.',true,false,state.readOnly);}).fail(function(m){var cached=state.siteCache[id];state.readOnly=true;if(cached){render(cached);feedback('Site is unreachable; showing the last catalog loaded in this browser. Editing is disabled.',false,false,true);}else{state.services=[];state.models=[];state.previewCache={};feedback(m,false,false);$('#ucm-services-table tbody').html('<tr><td colspan="7" class="text-danger">'+esc(m)+'</td></tr>');applyReadOnly();}});}
function typeLabel(v){return {directory:'Company directory',info:'Phone/site information',diallist:'Quick-dial list',text:'Read-only notice'}[v]||v;}
function formatLabel(v){return {cisco:'Cisco XML',cisco_legacy:'Cisco 7940/7960',yealink:'Yealink',grandstream:'Grandstream'}[v]||v;}
function modelLabel(key){var found=state.models.filter(function(m){return m.key===key;})[0];return found?(found.vendor+' '+found.model):key;}
function targetSummary(s){var settings=s.settings||{},formats=(settings.formats||allFormats).map(formatLabel),models=settings.target_models||[];return formats.join(', ')+(models.length?'; '+models.map(modelLabel).join(', '):'; all supported models');}
function render(r){state.services=r.services||[];state.models=r.models||[];state.previewCache=r.preview_cache||{};var rows=state.services.map(function(s,index){var result=s.service_type==='diallist'?((s.settings.items||[]).length+' destination(s)'):(s.service_type==='text'?'Notice screen':(s.service_type==='directory'?'Managed AD/manual directory':'Live phone and site details')),up=index===0?' disabled':'',down=index===state.services.length-1?' disabled':'';return '<tr><td><div class="btn-group btn-group-xs" role="group" aria-label="Reorder '+esc(s.name)+'"><button class="btn btn-default ucm-service-move" data-id="'+esc(s.id)+'" data-dir="-1" title="Move up"'+up+'><i class="fa fa-arrow-up"></i></button><button class="btn btn-default ucm-service-move" data-id="'+esc(s.id)+'" data-dir="1" title="Move down"'+down+'><i class="fa fa-arrow-down"></i></button></div><br><small>'+esc(s.menu_order)+'</small></td><td><strong>'+esc(s.name)+'</strong><br><code>'+esc(s.service_key)+'</code></td><td>'+esc(typeLabel(s.service_type))+'</td><td><small>'+esc(targetSummary(s))+'</small></td><td><span class="label '+(Number(s.enabled)?'label-success':'label-default')+'">'+(Number(s.enabled)?'Published':'Hidden')+'</span></td><td>'+esc(result)+'</td><td class="text-right"><button class="btn btn-xs btn-default ucm-service-preview" data-key="'+esc(s.service_key)+'">Preview</button> <button class="btn btn-xs btn-primary ucm-service-edit" data-id="'+esc(s.id)+'">Edit</button> '+(Number(s.locked)?'':'<button class="btn btn-xs btn-danger ucm-service-delete" data-id="'+esc(s.id)+'">Delete</button>')+'</td></tr>';}).join('');$('#ucm-services-table tbody').html(rows||'<tr><td colspan="7" class="text-muted">No services.</td></tr>');
 var caps=(r.capabilities||[]).map(function(c){return '<tr><td><strong>'+esc(c.fleet)+'</strong></td><td>'+esc(c.entry)+'</td><td>'+(c.catalog?'Yes':'Directory only')+'</td><td>'+(c.dial?'Yes':'No')+'</td><td>'+esc(c.note)+'</td></tr>';}).join('');$('#ucm-services-capabilities tbody').html(caps);var urls='';$.each(r.urls||{},function(k,v){urls+='<dt>'+esc(k)+'</dt><dd><code>'+esc(v)+'</code></dd>';});$('#ucm-services-urls').html(urls||'<p class="text-muted">Bearer URLs are not stored in offline snapshots.</p>');applyReadOnly();}
function dialRow(item){item=item||{};return $('<div class="row ucm-service-dial-row" style="margin-bottom:8px">').append($('<div class="col-sm-5">').append($('<input class="form-control ucm-dial-label" maxlength="40" placeholder="Label, for example Security">').val(item.label||'')),$('<div class="col-sm-5">').append($('<input class="form-control ucm-dial-number" maxlength="64" placeholder="Number or feature code">').val(item.number||'')),$('<div class="col-sm-2">').append('<button type="button" class="btn btn-danger ucm-service-remove-dial"><i class="fa fa-trash"></i></button>'));}
function selectedFormats(){var formats=[];$('.ucm-service-format:checked').each(function(){formats.push(this.value);});return formats;}
function populateEditorModels(selected){selected=selected||$('#ucm-service-models').val()||[];var formats=selectedFormats(),html=state.models.filter(function(m){return formats.indexOf(m.format)!==-1;}).map(function(m){return '<option value="'+esc(m.key)+'"'+(selected.indexOf(m.key)!==-1?' selected':'')+'>'+esc(m.vendor+' '+m.model)+'</option>';}).join('');$('#ucm-service-models').html(html);}
function openEditor(s){if(state.readOnly)return;s=s||{service_type:'diallist',enabled:1,menu_order:50,settings:{items:[],formats:allFormats,target_models:[]}};var f=$('#ucm-service-form')[0];f.reset();$('[name=id]',f).val(s.id||'');$('[name=locked]',f).val(s.locked||0);$('[name=name]',f).val(s.name||'');$('[name=service_key]',f).val(s.service_key||'').prop('readonly',!!s.id);var built=Number(s.locked)===1,$type=$('[name=service_type]',f);$('[name=locked_service_type]',f).val(built?s.service_type:'');$type.val(built?'diallist':(s.service_type||'diallist')).toggle(!built);$('#ucm-service-protected-purpose').val(built?typeLabel(s.service_type):'').toggle(built);$('#ucm-service-type-help').text(built?'Protected singleton: its purpose and stable route cannot change. Its label, order, visibility and phone targets can change. Hidden means absent from Services, not removal of the native phonebook.':'Add a Quick-dial list or read-only Notice. The protected Directory and Phone Information services already exist above.');$('[name=menu_order]',f).val(s.menu_order||50);$('[name=enabled]',f).prop('checked',Number(s.enabled)===1);$('[name=body]',f).val((s.settings||{}).body||'');var formats=(s.settings||{}).formats||allFormats;$('.ucm-service-format',f).each(function(){$(this).prop('checked',formats.indexOf(this.value)!==-1);});populateEditorModels((s.settings||{}).target_models||[]);$('#ucm-service-dial-rows').empty();((s.settings||{}).items||[]).forEach(function(i){$('#ucm-service-dial-rows').append(dialRow(i));});if(!$('#ucm-service-dial-rows').children().length)$('#ucm-service-dial-rows').append(dialRow());$('#ucm-service-editor-title').text(s.id?'Edit '+s.name:'Add phone service');$('#ucm-service-editor').show();toggleType();$('html,body').animate({scrollTop:$('#ucm-service-editor').offset().top-70},200);}
function closeEditor(){$('#ucm-service-editor').hide();$('[name=service_type]').show();$('#ucm-service-protected-purpose').hide();}
function editorType(){return $('[name=locked_service_type]').val()||$('[name=service_type]').val();}
function toggleType(){var t=editorType();$('#ucm-service-text').toggle(t==='text');$('#ucm-service-dials').toggle(t==='diallist');}
function serviceByKey(key){return state.services.filter(function(s){return s.service_key===key;})[0];}
function populatePreviewModels(preferred){var format=$('#ucm-services-preview-format').val(),models=state.models.filter(function(m){return m.format===format;}),html='<option value="">Unknown / family-only</option>';models.forEach(function(m){html+='<option value="'+esc(m.key)+'">'+esc(m.vendor+' '+m.model)+'</option>';});$('#ucm-services-preview-model').html(html);var service=serviceByKey(state.previewKey),targets=((service||{}).settings||{}).target_models||[],choice=preferred||targets.filter(function(k){return models.some(function(m){return m.key===k;});})[0]||'';$('#ucm-services-preview-model').val(choice);}
function cachedWarning(service,format,model){if(!Number(service.enabled))return 'This service is hidden; the preview is not currently published.';var settings=service.settings||{},formats=settings.formats||allFormats,models=settings.target_models||[];if(formats.indexOf(format)===-1)return 'This service is excluded from the selected phone family.';if(models.length&&!model)return 'This service targets exact models; select one to evaluate applicability.';if(models.length&&models.indexOf(model)===-1)return 'This service is excluded from the selected phone model.';return '';}
function showCachedPreview(reason){var format=$('#ucm-services-preview-format').val(),cached=((state.previewCache[state.previewKey]||{})[format]),service=serviceByKey(state.previewKey);if(!cached||!service)return false;var warning=cachedWarning(service,format,$('#ucm-services-preview-model').val());$('#ucm-services-preview-code').text(cached.xml||'');$('#ucm-services-preview-warning').text(warning||'Cached output uses redacted placeholder URLs.').toggle(true);$('#ucm-services-preview').modal('show');feedback(reason||'Showing the cached, token-free output preview.',true,false,true);return true;}
function preview(){var format=$('#ucm-services-preview-format').val(),model=$('#ucm-services-preview-model').val();if(state.readOnly){if(!showCachedPreview('Site is offline; showing the last cached, token-free output preview.'))feedback('No cached preview is available for this service.',false,false);return;}call({op:'preview',service_key:state.previewKey,format:format,model_key:model},'Rendering preview…').done(function(r){$('#ucm-services-preview-code').text(r.xml||'');$('#ucm-services-preview-warning').text(r.warning||'').toggle(!!r.warning);$('#ucm-services-preview').modal('show');feedback('Preview rendered on '+siteName()+'.',true,false);}).fail(function(m){if(!showCachedPreview('Live preview failed; showing the last cached, token-free output.'))feedback(m,false,false);});}
$('#ucm-services-site').on('change',load);$('#ucm-services-refresh').on('click',load);$('#ucm-service-add').on('click',function(){openEditor();});$('#ucm-service-cancel').on('click',closeEditor);$('[name=service_type]').on('change',toggleType);$('#ucm-service-add-dial').on('click',function(){$('#ucm-service-dial-rows').append(dialRow());});$(document).on('click','.ucm-service-remove-dial',function(){$(this).closest('.ucm-service-dial-row').remove();});
$('.ucm-service-format').on('change',function(){populateEditorModels();});
$(document).on('click','.ucm-service-edit',function(){var id=Number($(this).data('id')),s=state.services.filter(function(x){return Number(x.id)===id;})[0];if(s)openEditor(s);});$(document).on('click','.ucm-service-delete',function(){var id=$(this).data('id');if(!confirm('Delete this service from '+siteName()+'?'))return;call({op:'delete',id:id},'Deleting service…').done(function(r){remember(r);render(r);feedback(r.message,true,false);}).fail(function(m){feedback(m,false,false);});});
$(document).on('click','.ucm-service-move',function(){if(state.readOnly)return;var id=Number($(this).data('id')),dir=Number($(this).data('dir')),ids=state.services.map(function(s){return Number(s.id);}),index=ids.indexOf(id),other=index+dir;if(index<0||other<0||other>=ids.length)return;var swap=ids[index];ids[index]=ids[other];ids[other]=swap;call({op:'reorder',ids:JSON.stringify(ids)},'Saving service order…').done(function(r){remember(r);render(r);feedback(r.message,true,false);}).fail(function(m){feedback(m,false,false);});});
$(document).on('click','.ucm-service-preview',function(){state.previewKey=String($(this).data('key'));populatePreviewModels();preview();});$('#ucm-services-preview-format').on('change',function(){populatePreviewModels();preview();});$('#ucm-services-preview-model').on('change',preview);
$('#ucm-service-form').on('submit',function(e){e.preventDefault();if(state.readOnly)return;var f=this,items=[],formats=selectedFormats(),models=$('#ucm-service-models').val()||[];$('#ucm-service-dial-rows .ucm-service-dial-row').each(function(){items.push({label:$(this).find('.ucm-dial-label').val(),number:$(this).find('.ucm-dial-number').val()});});call({op:'save',id:$('[name=id]',f).val(),name:$('[name=name]',f).val(),service_key:$('[name=service_key]',f).val(),service_type:editorType(),menu_order:$('[name=menu_order]',f).val(),enabled:$('[name=enabled]',f).is(':checked')?1:0,settings:JSON.stringify({body:$('[name=body]',f).val(),items:items,formats:formats,target_models:models})},'Saving service on '+siteName()+'…').done(function(r){remember(r);render(r);closeEditor();feedback(r.message,true,false);}).fail(function(m){feedback(m,false,false);});});
load();
})(jQuery);
</script>
